p = 61
residues = {}
# Calculate x^3 mod 61 for x = 0 to 60
for x in range(p):
    r = pow(x, 3, p)
    if r not in residues:
        residues[r] = 0
    residues[r] += 1

print("Distribution N3(r) for r = 0 to 60:")
for r in range(p):
    print(f"N3({r}) = {residues.get(r, 0)}")

# Verification checks
total_count = sum(residues.values())
num_non_zero_residues_with_count_3 = 0
non_zero_residues = [r for r in residues if r != 0]

for r in non_zero_residues:
    if residues[r] == 3:
        num_non_zero_residues_with_count_3 += 1

print(f"\nTotal count (sum N3(r)): {total_count}")
print(f"Number of non-zero residues with N3(r) = 3: {num_non_zero_residues_with_count_3}")

p = 61
S2 = {r: 0 for r in range(p)}

# Iterate over all pairs (a, b) where a, b are residues modulo 61 (0 to 60)
for a in range(p):
    for b in range(p):
        R = (a*a + b*b) % p
        S2[R] += 1

print("S2(R) frequency map for R = 0 to 60:")
for R in range(p):
    print(f"R={R}: S2({R}) = {S2[R]}")

# Check the sum of counts
total_solutions = sum(S2.values())
print(f"Total solutions: {total_solutions}")
